/// A decoded bytecode instruction.
#[derive(Debug, Clone, PartialEq)]
pub struct Instruction {
    /// Offset of this instruction in the code array.
    pub pc: u16,
    /// Size in bytes (including the opcode and, for `Wide`, the prefix).
    pub size: u16,
    pub op: Opcode,
    /// First operand: cp index / local slot / absolute branch target / immediate.
    pub a: i32,
    /// Second operand: iinc amount / invokeinterface count / multianewarray dims.
    pub b: i32,
    /// Switch data for Tableswitch/Lookupswitch.
    pub switch_data: Option<Box<SwitchData>>,
}

#[derive(Debug, Clone, PartialEq)]
pub enum SwitchData {
    /// `targets[i]` is the absolute branch target for key `low + i`.
    Table { default: u16, low: i32, targets: Vec<u16> },
    /// `(match, absolute target)` pairs sorted by match value.
    Lookup { default: u16, pairs: Vec<(i32, u16)> },
}

